function resolveLocationConfig(locationId) {
    const loc = LOCATIONS[String(locationId)];
    if (!loc) return null;

    // Resolve insurance: group base + additions - removals
    let insuranceList = INSURANCE_GROUPS[loc.ig] || '';
    if (loc.ia) {
        insuranceList = insuranceList + '|' + loc.ia;
    }
    if (loc.ir) {
        const removals = loc.ir.split('|').map(s => s.trim().toLowerCase());
        insuranceList = insuranceList.split('|').filter(c => !removals.includes(c.trim().toLowerCase())).join('|');
    }

    return {
        brand: loc.brand,
        location_phone: loc.phone,
        location_fax: loc.fax,
        parking_info: loc.parking,
        website_instructions: loc.website,
        business_hours: loc.hours,
        lines_of_business: loc.lob,
        accepted_insurance: insuranceList,
        dmo_rules: DMO_RULES[loc.state] || '',
        medicaid_plans: loc.med,
        baby_wellness_available: loc.bw,
        baby_wellness_max_age: loc.bwAge,
        new_patient_special: loc.nps,
        routing_rules_handle: loc.rh,
        routing_rules_transfer: loc.rt,
        special_rules: loc.sr
    };
}

